import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC-0017: web.search and web.fetch Capability Mapping","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/rfcs/0017-web-search-and-fetch-capability-mapping.md"},"headers":[],"relativePath":"sovereign-os/rfcs/0017-web-search-and-fetch-capability-mapping.md","filePath":"sovereign-os/rfcs/0017-web-search-and-fetch-capability-mapping.md"}'),n={name:"sovereign-os/rfcs/0017-web-search-and-fetch-capability-mapping.md"};function s(r,e,c,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="rfc-0017-web-search-and-web-fetch-capability-mapping" tabindex="-1">RFC-0017: <code>web.search</code> and <code>web.fetch</code> Capability Mapping <a class="header-anchor" href="#rfc-0017-web-search-and-web-fetch-capability-mapping" aria-label="Permalink to &quot;RFC-0017: \`web.search\` and \`web.fetch\` Capability Mapping&quot;">​</a></h1><p><strong>Status:</strong> Accepted (2026-08-21, project creator) <strong>Author:</strong> Project creator and Claude <strong>Created:</strong> 2026-08-21 <strong>Reviewers:</strong> Project creator <strong>Target phase:</strong> <a href="./../roadmap/01-2-local-conversation-capabilities.html">Milestone 01.2, Local Conversation and Capabilities</a><strong>Supersedes:</strong> None</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Register <code>web.search</code> and <code>web.fetch</code> against <a href="./0003-capability-contract.html">RFC-0003</a>&#39;s contract, backed by a locally deployed SearXNG instance per <a href="./../research/searxng-deployment-assessment.html">docs/research/searxng-deployment-assessment.md</a>. Both capabilities are <code>read_only</code>/<code>external</code>, which RFC-0003&#39;s structural table already fixes as <code>confirmation: required</code> — the part this RFC adds that RFC-0006 didn&#39;t need is a concrete design for the confirmation pause/resume flow RFC-0004 specified architecturally but left as &quot;implementation, not architecture,&quot; and for the opt-in policy state (<code>external_enabled</code>) the executor already gates on but nothing currently sets. <code>web.search</code>/<code>web.fetch</code> are also the first capabilities that genuinely send household-originated content outside the device, so this RFC additionally fixes the SSRF-safe fetch policy the milestone plan names (&quot;restricted by URL and content safety policy&quot;) but never specified.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p><a href="./../adrs/0004-provider-neutral-assistant-and-web-search.html">ADR-0004</a> decided SearXNG is the initial <code>web.search</code> provider and named &quot;document SearXNG deployment, upstream configuration, retention, and failure behavior&quot; as open follow-up. <a href="./../research/searxng-deployment-assessment.html">searxng-deployment-assessment.md</a> closed the deployment half of that gap. What remains is the capability mapping itself — the same relationship <a href="./../research/pihole-api-assessment.html">pihole-api-assessment.md</a> had to <a href="./0006-pihole-capability-mapping.html">RFC-0006</a>.</p><p>Three concrete gaps block <code>web.search</code>/<code>web.fetch</code> from being usable, all visible directly in the running code today, not hypothetical:</p><ol><li><strong>Not registered.</strong> <code>sovereign_conversation.py</code>&#39;s <code>build_registry()</code> says so explicitly in its own comment: <em>&quot;web.search/web.fetch are not registered here; they don&#39;t exist yet (blocked on the SearXNG deployment decision).&quot;</em></li><li><strong>No confirmation flow.</strong> Even once registered, <code>read_only</code>+<code>external</code> is <code>confirmation: required</code> per RFC-0003&#39;s table. The executor-level primitives for this already exist and are unit-tested — <code>sovereign_capabilities.ConfirmationStore.issue()</code>/<code>.consume()</code>, and <code>invoke(..., confirmation_token=...)</code> (see <code>tests/test_capabilities.py</code>, <code>ConfirmationTokenTests</code>) — but the Conversation Service layer above them does not use them. Its own comment says so: <em>&quot;Confirmation-required capabilities are detected and refused with a clear error, not silently executed and not given a working pause-and-resume flow across requests... this path is exercised by nothing real yet, but must still fail loudly rather than pretend to support it.&quot;</em> RFC-0004 fixed the architecture of this flow (§ Confirmation Flow) but explicitly deferred &quot;how a denied/expired confirmation is presented to the user specifically&quot; as a UI design question for whichever capability needs it first — that&#39;s this RFC.</li><li><strong>No policy state.</strong> The executor already gates <code>external</code>-classified capabilities on <code>policy.get(&quot;external_enabled&quot;, False)</code> (<code>sovereign_capabilities.invoke</code>, stage 3) — but <code>bin/sovereign-conversation</code>&#39;s <code>_handle_message</code> never passes a <code>policy</code> argument to <code>process_turn()</code> at all, so it silently defaults to <code>{}</code>, which means <code>external_enabled</code> is always <code>False</code> today. There is no persisted policy state anywhere for this to read even if it were wired up. Registering <code>web.search</code>/<code>web.fetch</code> without fixing this would ship two capabilities the executor can never actually run.</li></ol><p>Without this RFC, an implementer would have to invent the confirmation wire format and the SSRF-safe fetch policy ad hoc — exactly the kind of consequential, safety-relevant decision this project&#39;s RFC process exists to make deliberately rather than by omission (the same rationale RFC-0006 gave for the Pi-hole privacy boundary).</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Register <code>web.search</code> and <code>web.fetch</code> against RFC-0003&#39;s contract: schemas, classification (already fixed: <code>read_only</code>/<code>external</code>/<code>required</code>), and bounds.</li><li>Design the confirmation pause/resume wire format <code>bin/sovereign-conversation</code> needs to actually surface a pending <code>required</code>-confirmation decision to the client and accept an approval/denial back, on top of the already-implemented <code>ConfirmationStore</code> primitives.</li><li>Fix where the <code>external_enabled</code> opt-in policy flag is persisted, its safe default, and how <code>process_turn()</code> reads it.</li><li>Fix the SSRF-safe URL-fetch policy <code>web.fetch</code> must enforce, since it is the first capability that lets a model-proposed argument influence what the device&#39;s own network stack contacts.</li><li>Fix the SearXNG-backed implementation specifics research left open: <code>settings.yml</code>&#39;s <code>image_proxy</code> decision, and upstream engine selection.</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>Re-deciding that SearXNG is the provider — closed by ADR-0004.</li><li>Re-deriving the confirmation <em>architecture</em> (proposal surfaced as a pending decision, single-use time-bounded token, model never sees the token, denial is a normal audited outcome) — fixed by RFC-0004. This RFC only fixes the parts RFC-0004 named as implementation-level and left open.</li><li>The Console UI&#39;s actual approve/deny prompt and the settings toggle that sets <code>external_enabled</code> — this RFC fixes the API contract and storage location both depend on, the same way RFC-0006 fixed Pi-hole&#39;s API contract without itself building Console UI. Building those is necessary follow-up implementation work, named in Acceptance Criteria, not built here.</li><li>Measuring real resource footprint on this project&#39;s actual Raspberry Pi 5 device under real concurrent load, and hardware-qualifying any of this — still open per <a href="./../research/searxng-deployment-assessment.html">searxng-deployment-assessment.md</a>&#39;s Addendum, unchanged by this RFC. (The real ARM64 image digest itself has since been pinned and embedded — see <code>image-builder/sovereign/searxng-image.env</code> — but that&#39;s image-builder work this RFC&#39;s capability mapping doesn&#39;t depend on being reviewed first.)</li><li>General web crawling, recursive link-following, or fetching more than one page per <code>web.fetch</code> invocation — explicit milestone non-scope (&quot;no generic network tool&quot;).</li><li>Any capability beyond <code>web.search</code>/<code>web.fetch</code> — Home Assistant&#39;s future capabilities (Milestone 5) will reuse this RFC&#39;s confirmation wire format once they exist, but are not designed here.</li></ul><h2 id="context-and-evidence" tabindex="-1">Context and Evidence <a class="header-anchor" href="#context-and-evidence" aria-label="Permalink to &quot;Context and Evidence&quot;">​</a></h2><ul><li><a href="./../adrs/0004-provider-neutral-assistant-and-web-search.html">ADR-0004</a> (Accepted): SearXNG is the initial <code>web.search</code> provider; <code>web.search</code> and <code>web.fetch</code> are separate capabilities; the model receives no generic network tool; search is explicitly enabled/approved and visibly communicates the query and external boundary.</li><li><a href="./0002-local-conversation-and-inference-runtime.html">RFC-0002</a> (Accepted) named &quot;the <code>web.search</code>/<code>web.fetch</code> privacy design in full detail&quot; as a Non-Goal, &quot;tracked separately&quot; — this RFC is that separate document.</li><li><a href="./0003-capability-contract.html">RFC-0003</a> (Accepted): both capabilities are already classified in its own Initial Capability Classification table — <code>read_only</code>/<code>external</code>/<code>required</code> for both — and its Confirmation Model table derives that classification structurally, not as a per-capability choice this RFC can revisit.</li><li><a href="./0004-ai-capability-invocation.html">RFC-0004</a> (Accepted): fixes the confirmation flow&#39;s architecture (§ Confirmation Flow) and the untrusted-forever boundary on capability results, and explicitly defers &quot;exact confirmation-token format and expiry duration&quot; and &quot;how a denied/expired confirmation is presented to the user specifically&quot; as implementation-level, to be fixed by whichever capability needs them first.</li><li><code>image-builder/sovereign/appliance/lib/sovereign_capabilities.py</code>, read directly: <code>ConfirmationStore</code> (token issue/consume, single-use, time-bounded via <code>DEFAULT_CONFIRMATION_TTL_SECONDS = 120</code>), and <code>invoke()</code>&#39;s stage-3 policy gate (<code>policy.get(&quot;external_enabled&quot;, False)</code>) and stage-4 confirmation gate — both already implemented and covered by <code>tests/test_capabilities.py</code>&#39;s <code>ConfirmationTokenTests</code> and <code>test_external_capability_rejected_when_policy_disabled</code>/ <code>test_required_confirmation_rejected_without_token</code>.</li><li><code>image-builder/sovereign/appliance/lib/sovereign_conversation.py</code> and <code>image-builder/sovereign/appliance/bin/sovereign-conversation</code>, read directly: confirm, in their own comments and code, all three gaps this RFC closes (not registered; confirmation refused outright; no <code>policy</code> argument ever passed).</li><li><a href="./../research/searxng-deployment-assessment.html">docs/research/searxng-deployment-assessment.md</a> (Concluded, desk research, later live-verified in its own Addendum): image (<code>ghcr.io/searxng/searxng</code>), local port (<code>8093</code>, avoiding the collision with Pi-hole&#39;s existing <code>8080</code>), required <code>settings.yml</code> overrides (<code>formats: [html, json]</code>, <code>autocomplete: &quot;&quot;</code>, <code>limiter: false</code> confirmed correct), the <code>SEARXNG_SECRET</code> environment-variable mechanism (confirmed real and required — no <code>_FILE</code> convention exists), and the JSON search API&#39;s request shape (<code>q</code>/<code>categories</code>/<code>language</code>/<code>pageno</code>/<code>time_range</code>/<code>safesearch</code>) and real response shape (confirmed live: <code>results[]</code> entries carry <code>title</code>/<code>url</code>/<code>content</code> among other fields this RFC&#39;s schema doesn&#39;t surface). This RFC still decides <code>image_proxy</code> itself (see Proposal).</li><li><a href="./../roadmap/01-2-local-conversation-capabilities.html">docs/roadmap/01-2-local-conversation-capabilities.md</a> §6 (Web Search and Privacy): &quot;search only when the user requests it or the user approves a proposed search,&quot; &quot;show the exact query before or while it is sent,&quot; &quot;do not silently mix private household context into search queries,&quot; &quot;strip capability secrets and unnecessary identifiers,&quot; &quot;return source URLs and distinguish fetched evidence from model knowledge,&quot; &quot;support disabling web search entirely.&quot; §4 names <code>web.fetch</code> as &quot;restricted by URL and content safety policy&quot; without specifying what that policy is — this RFC&#39;s job.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><h3 id="web-search" tabindex="-1"><code>web.search</code> <a class="header-anchor" href="#web-search" aria-label="Permalink to &quot;\`web.search\`&quot;">​</a></h3><ul><li><strong>Purpose:</strong> answer questions the model cannot answer from its own training or from a registered local capability, by querying the self-hosted SearXNG instance.</li><li><strong>Arguments:</strong> <code>{ &quot;query&quot;: string (required, 1-500 chars), &quot;time_range&quot;: &quot;day&quot; | &quot;month&quot; | &quot;year&quot; (optional) }</code>. No <code>categories</code> or <code>safesearch</code> argument in this first pass — SearXNG&#39;s own defaults for both are acceptable for a general-purpose assistant, and RFC-0003&#39;s &quot;bounded, enumerated argument set&quot; precedent (RFC-0006&#39;s <code>period</code> argument) favors the smallest schema that answers the milestone&#39;s real questions over speculative flexibility. <code>time_range</code> is optional because most questions (&quot;what&#39;s the weather saying,&quot; &quot;who won&quot;) aren&#39;t time-scoped explicitly.</li><li><strong>Result:</strong> <code>{ &quot;query&quot;: string, &quot;results&quot;: [ { &quot;title&quot;: string, &quot;url&quot;: string, &quot;snippet&quot;: string } ], &quot;result_count&quot;: int, &quot;retrieved_at&quot;: timestamp }</code>. At most 5 results, no pagination argument — the same &quot;summary endpoint by design, not an export&quot; bound RFC-0006 applied to <code>pihole.summary</code>. <code>query</code> is echoed back in the result (not just the argument) so the structured citation object the client renders is self-contained per RFC-0004&#39;s &quot;distinguished from generated prose&quot; requirement, without the client needing to correlate it back to the original proposal&#39;s arguments.</li><li><strong>Classification:</strong> <code>read_only</code>, <code>external</code> (fixed by RFC-0003), <code>required</code> confirmation (derived, not chosen).</li><li><strong>Bounds:</strong> <code>timeout_seconds=10</code> (SearXNG runs locally; a slow response indicates an unresponsive upstream engine, not normal latency), <code>max_result_bytes</code> left at <code>DEFAULT_MAX_RESULT_BYTES</code> (64KiB — five short results comfortably fit), <code>max_invocations_per_turn=1</code> — matching every other registered capability&#39;s default rather than special-casing search to allow rapid-fire repeated queries in one turn.</li></ul><h3 id="web-fetch" tabindex="-1"><code>web.fetch</code> <a class="header-anchor" href="#web-fetch" aria-label="Permalink to &quot;\`web.fetch\`&quot;">​</a></h3><ul><li><strong>Purpose:</strong> retrieve the actual content of a specific URL — typically one <code>web.search</code> just returned, but not restricted to only those (a user may paste a URL directly and ask about it; RFC-0004&#39;s untrusted-forever boundary already governs what happens to fetched content regardless of how the URL was obtained, so provenance-based restriction would add complexity without closing a real gap the SSRF policy below doesn&#39;t already close).</li><li><strong>Arguments:</strong> <code>{ &quot;url&quot;: string (required, http/https only) }</code>.</li><li><strong>Result:</strong> <code>{ &quot;url&quot;: string, &quot;final_url&quot;: string, &quot;content_type&quot;: string, &quot;text&quot;: string, &quot;truncated&quot;: bool, &quot;redirected&quot;: bool, &quot;retrieved_at&quot;: timestamp }</code>. (Implementation note: <code>redirected</code> was added during implementation — this bullet originally omitted it while the SSRF-Safe Fetch Policy section below already described the flag in prose; the two are now consistent.) <code>text</code> is plain-text extracted content — built on the standard library&#39;s <code>html.parser.HTMLParser</code> (tags, <code>&lt;script&gt;</code>, and <code>&lt;style&gt;</code> content excluded), not a third-party HTML/rendering dependency — truncated at <code>max_result_bytes</code> if the page is larger, with <code>truncated: true</code> set rather than silently dropping the tail. <code>final_url</code> equals <code>url</code> for an ordinary fetch; on a redirect response it instead holds the redirect&#39;s <code>Location</code> target, and <code>redirected</code> is <code>true</code> — no redirect is ever followed automatically (see SSRF-Safe Fetch Policy below), so <code>final_url</code> never reflects a same-origin hop that was silently taken.</li><li><strong>Classification:</strong> <code>read_only</code>, <code>external</code>, <code>required</code> confirmation.</li><li><strong>Bounds:</strong> <code>timeout_seconds=15</code> (a real external server&#39;s own latency, not this device&#39;s — longer than <code>web.search</code>&#39;s local-instance budget is deliberate, not an oversight), <code>max_result_bytes</code> left at <code>DEFAULT_MAX_RESULT_BYTES</code>, <code>max_invocations_per_turn=1</code>.</li></ul><h3 id="ssrf-safe-fetch-policy" tabindex="-1">SSRF-Safe Fetch Policy <a class="header-anchor" href="#ssrf-safe-fetch-policy" aria-label="Permalink to &quot;SSRF-Safe Fetch Policy&quot;">​</a></h3><p><code>web.fetch</code> is the first capability where a model-supplied argument influences what the device&#39;s own network stack contacts, which is a different risk class than the untrusted-content boundary RFC-0004 already covers (that boundary governs what fetched <em>content</em> is allowed to do; this policy governs what fetching is allowed to <em>reach</em>). The implementation must, before making any request:</p><ol><li><strong>Scheme allowlist.</strong> Reject anything but <code>http://</code>/<code>https://</code> outright — no <code>file://</code>, <code>ftp://</code>, <code>gopher://</code>, or any scheme that could reach local files or unexpected protocols.</li><li><strong>Resolve before connecting, and check the resolved address, not the literal hostname.</strong> A hostname that <em>looks</em> external can still resolve to an internal address (DNS rebinding), so the check must happen against the actual IP the connection is about to use, immediately before connecting — not a one-time hostname-string check earlier in the pipeline that a second, later DNS lookup could bypass.</li><li><strong>Reject private, loopback, link-local, and multicast destination addresses</strong> — RFC1918 (<code>10.0.0.0/8</code>, <code>172.16.0.0/12</code>, <code>192.168.0.0/16</code>), loopback (<code>127.0.0.0/8</code>, <code>::1</code>), link-local (<code>169.254.0.0/16</code>, <code>fe80::/10</code>), and multicast/reserved ranges. This is the concrete, real-stakes reason the check matters on this specific device: <code>127.0.0.1</code> on this appliance is Pi-hole&#39;s admin API (<code>8080</code>), console-auth (<code>8091</code>), the Conversation Service itself (<code>8092</code>), and llama-server (<code>8081</code>) — a <code>web.fetch</code> proposal targeting any of them would be a real internal-service-reconnaissance vector, not a theoretical one, and the household LAN behind it hosts real devices (routers, other appliances) an external-facing capability must never be able to reach.</li><li><strong>No automatic redirect-following.</strong> If the response is a redirect, <code>web.fetch</code> returns that fact (<code>final_url</code> set to the redirect target, <code>text</code> empty, a <code>redirected: true</code> flag) rather than silently following it — blind redirect-following is a well-known SSRF bypass (a public URL redirecting to an internal one after the first check already passed). A model that wants the redirect target fetches it as an explicit second <code>web.fetch</code> proposal, which the confirmation flow below surfaces and the SSRF checks re-apply to independently.</li><li><strong>Content-type allowlist.</strong> Only <code>text/html</code>, <code>text/plain</code>, and <code>application/json</code> are extracted; anything else (binary, executable, archive) is rejected before the body is read, not merely not rendered.</li><li><strong>Size cap enforced while streaming</strong>, not after a full download — a multi-gigabyte response must not be fully retrieved before its size is checked.</li></ol><p>This is deliberately stricter than &quot;restricted by URL,&quot; the milestone plan&#39;s own phrasing — it is restricted by <em>resolved destination and response shape</em>, which is the only version of that restriction that actually holds against DNS rebinding and redirect-based bypasses.</p><h3 id="confirmation-pause-resume-wire-format" tabindex="-1">Confirmation Pause/Resume Wire Format <a class="header-anchor" href="#confirmation-pause-resume-wire-format" aria-label="Permalink to &quot;Confirmation Pause/Resume Wire Format&quot;">​</a></h3><p><code>ConfirmationStore.issue()</code>/<code>.consume()</code> and <code>invoke(..., confirmation_token=...)</code> already implement RFC-0004&#39;s confirmation <em>mechanics</em>. What&#39;s missing is the request/response shape that lets a client actually drive that mechanism across two HTTP requests. This RFC fixes it:</p><ul><li>When <code>process_turn()</code> encounters a <code>required</code>-confirmation proposal that has passed RFC-0003&#39;s resolve/validate/policy stages, it no longer raises <code>confirmation_unsupported</code>. Instead it calls <code>confirmation_store.issue(name, version, arguments)</code> and <strong>halts that round without executing</strong>, returning a <code>pending_confirmation</code> object instead of continuing to propose/execute further in the same turn: <code>{ &quot;token&quot;: string, &quot;capability&quot;: string, &quot;version&quot;: int, &quot;arguments&quot;: object, &quot;expires_in_seconds&quot;: int }</code>. <code>arguments</code> is included verbatim and unredacted — RFC-0004 requires the exact external-bound content (the literal search query, the literal URL) to be disclosed before approval, and the milestone plan&#39;s &quot;show the exact query&quot; requirement is not satisfied by a summary or a capability name alone.</li><li><code>POST /api/v1/conversation/message</code>&#39;s response gains an optional top-level <code>pending_confirmation</code> field (absent/<code>null</code> on every turn that didn&#39;t hit this path — no shape change for <code>system.health</code>/Pi-hole turns). When present, <code>text</code> describes the situation in prose (e.g., the model&#39;s own turn narrating that it wants to search) and the client is responsible for prompting the user with the disclosed capability and arguments, not inferring intent from prose alone.</li><li><code>POST /api/v1/conversation/message</code>&#39;s request gains an optional <code>confirmation</code> field: <code>{ &quot;token&quot;: string, &quot;approve&quot;: bool }</code>. When present, the server does not start a new turn; it resolves the specific pending proposal the token identifies: <ul><li><code>approve: true</code> → <code>invoke()</code> is called with that <code>confirmation_token</code>, consuming it (single-use, enforced by <code>ConfirmationStore.consume()</code> already). Success appends the result to context and the turn continues (further rounds, up to the existing per-turn budget) exactly as an <code>automatic</code>-confirmation capability&#39;s result would.</li><li><code>approve: false</code>, or the token has expired (<code>DEFAULT_CONFIRMATION_TTL_SECONDS = 120</code>, unchanged — a concrete number already implemented and tested, not re-litigated here) → the proposal is recorded as a denial, appended to context as such per RFC-0004 (not a generic failure), and the turn continues without retrying it.</li><li>A <code>confirmation.token</code> that doesn&#39;t match any currently-pending entry (wrong token, already consumed, from a different conversation) is rejected with <code>400 INVALID_CONFIRMATION</code> — the same &quot;never trust the caller&#39;s own framing&quot; posture RFC-0003&#39;s schema validation already applies elsewhere.</li></ul></li><li>The model itself never sees the token — it is minted by the executor and returned only in the HTTP response the Console client reads, exactly matching RFC-0004&#39;s &quot;the model never receives, generates, or influences the confirmation token.&quot;</li><li><code>ConfirmationStore</code> remains in-memory, per-process (unchanged from today) — a token issued by one <code>sovereign-conversation</code> process restart-cycle does not survive it, which is an acceptable, disclosed limitation matching the Conversation Service&#39;s own existing statelessness (RFC-0002: &quot;no conversation storage... nothing is persisted here&quot;).</li></ul><h3 id="policy-state" tabindex="-1">Policy State <a class="header-anchor" href="#policy-state" aria-label="Permalink to &quot;Policy State&quot;">​</a></h3><ul><li>A new persisted file, <code>/data/sovereign/capabilities/policy.json</code>, holds <code>{ &quot;web_search_enabled&quot;: bool }</code>. (Implementation correction: this section originally proposed a top-level <code>/data/sovereign/policy.json</code> sibling. Before implementing, checking this project&#39;s own precedent — no <code>tmpfiles.d</code> usage anywhere in this repo; every <code>ReadWritePaths=</code> target is either pre-created by a root-run script like <code>proof-init</code>, or lazily created by the owning <code>DynamicUser</code> process itself — showed a new top-level file would need either a new <code>ReadWritePaths=</code> grant on an unverified not-yet-existing path, or a new root-run bootstrap step, exactly the class of gap that caused a real hardware-caught outage before, per the console-check-trigger qualification report&#39;s missing- grant bug. <code>capabilities/</code> is already granted to <code>sovereign-conversation.service</code> and already gets lazily created the same way by <code>append_audit_event()</code>; <code>policy.json</code> reuses that exact, already-shipped mechanism instead of inventing a second one.)</li><li><strong>Default: <code>false</code>.</strong> Matching the milestone plan&#39;s own policy (&quot;Web search is disabled by default or explicitly enabled during onboarding&quot;) and RFC-0003&#39;s general confirmation-model conservatism — an appliance that has never been configured must not silently start making external requests.</li><li><code>bin/sovereign-conversation</code> reads this file at the start of each <code>_handle_message</code> call (not cached at process start, so a change takes effect on the next message without a service restart — the same freshness expectation <code>sovereign-update check</code>&#39;s own on-demand reads already establish elsewhere in this project) and passes <code>policy={&quot;external_enabled&quot;: web_search_enabled}</code> into <code>process_turn()</code>, closing the gap where <code>policy</code> is never passed today.</li><li>Writing this file: <code>GET</code>/<code>POST /api/v1/conversation/policy</code>, authenticated the same way <code>/message</code> is (delegating to console-auth&#39;s <code>verify-mutating</code>), reusing this project&#39;s atomic-write convention (<code>.tmp</code> file, then rename) already established for <code>sovereign-pihole-password</code> and other per-device secrets. Console&#39;s Chat page renders this as a labeled toggle, loaded on sign-in and written on change — see Acceptance Criteria.</li></ul><h3 id="searxng-configuration-decisions" tabindex="-1">SearXNG Configuration Decisions <a class="header-anchor" href="#searxng-configuration-decisions" aria-label="Permalink to &quot;SearXNG Configuration Decisions&quot;">​</a></h3><p>Resolving the two items <a href="./../research/searxng-deployment-assessment.html">searxng-deployment-assessment.md</a> left open:</p><ul><li><strong><code>image_proxy: false</code> (off).</strong> <code>web.fetch</code>&#39;s result schema returns extracted text, not embedded images — nothing in this RFC&#39;s two capabilities renders an image inline, so proxying image bytes through SearXNG would add real request/bandwidth load for a capability that can&#39;t use the result. Revisit only if a future capability actually needs to reference image content.</li><li><strong>Upstream engine selection: keep SearXNG&#39;s own shipped defaults</strong>, rather than hand-curating a smaller engine list. No evidence gathered so far (this RFC&#39;s research or otherwise) identifies a specific engine as unreliable or objectionable for this use case, and curating a list without that evidence would be speculative narrowing, not a grounded decision. Revisit if real usage surfaces a specific problem engine.</li></ul><h2 id="interfaces-and-data-flow" tabindex="-1">Interfaces and Data Flow <a class="header-anchor" href="#interfaces-and-data-flow" aria-label="Permalink to &quot;Interfaces and Data Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Model proposes web.search({&quot;query&quot;: &quot;...&quot;})           [RFC-0004 flow]</span></span>
<span class="line"><span>    -&gt; RFC-0003 executor stages 1-3: resolve, validate arguments,</span></span>
<span class="line"><span>       check policy (external_enabled must be true, read fresh from</span></span>
<span class="line"><span>       /data/sovereign/capabilities/policy.json each request)</span></span>
<span class="line"><span>    -&gt; stage 3 fails (policy off) -&gt; rejection appended to context,</span></span>
<span class="line"><span>       model can tell the user web search is disabled</span></span>
<span class="line"><span>    -&gt; stage 3 passes, confirmation required (structural, both</span></span>
<span class="line"><span>       capabilities) -&gt; confirmation_store.issue() -&gt; round halts,</span></span>
<span class="line"><span>       pending_confirmation returned in the HTTP response instead of</span></span>
<span class="line"><span>       a normal result</span></span>
<span class="line"><span>    -&gt; Console prompts: &quot;web.search wants to search for &#39;&lt;query&gt;&#39; —</span></span>
<span class="line"><span>       this leaves your device. Approve?&quot;</span></span>
<span class="line"><span>    -&gt; user approves -&gt; client resubmits POST /message with</span></span>
<span class="line"><span>       {&quot;confirmation&quot;: {&quot;token&quot;: &quot;...&quot;, &quot;approve&quot;: true}}</span></span>
<span class="line"><span>    -&gt; confirmation_store.consume() (single-use) -&gt; invoke() proceeds</span></span>
<span class="line"><span>       through stages 5-6: SearXNG queried over the local, loopback-only</span></span>
<span class="line"><span>       instance (port 8093) -&gt; result shaped to web.search&#39;s declared</span></span>
<span class="line"><span>       result_schema -&gt; appended to context as a structured citation</span></span>
<span class="line"><span>    -&gt; turn continues (model may narrate, propose again within budget,</span></span>
<span class="line"><span>       or respond with prose)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    -&gt; OR user denies / token expires -&gt; denial appended to context,</span></span>
<span class="line"><span>       turn continues without a search result</span></span></code></pre></div><p><code>web.fetch</code>&#39;s flow is identical except stage 5 additionally runs the SSRF-safe fetch policy (resolve, check destination, no redirect-follow, content-type/size checks) before returning a result.</p><h2 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h2><ul><li><strong>Every</strong> <code>web.search</code>/<code>web.fetch</code> invocation requires per-invocation user confirmation — there is no automatic path for either capability, structurally, per RFC-0003&#39;s table. A successful prompt injection can cause a proposal, never an execution, matching RFC-0004&#39;s own framing.</li><li>The exact query/URL is disclosed to the user before approval, not summarized or hidden behind a capability name — the milestone plan&#39;s disclosure requirement is enforced by the <code>pending_confirmation</code> object&#39;s <code>arguments</code> field being the literal proposed arguments, not a paraphrase the Conversation Service could get wrong.</li><li>The <code>external_enabled</code> policy check happens fresh, per request, from persisted state — a household that has never opted in gets a structural rejection at stage 3, before a confirmation prompt is even generated, so &quot;disabled&quot; genuinely means no external contact is possible, not just &quot;no default.&quot; This directly satisfies the milestone plan&#39;s &quot;support disabling web search entirely.&quot;</li><li>The SSRF-safe fetch policy (resolve-then-check, no redirect-following, content-type/size limits) is the concrete mechanism behind the milestone plan&#39;s otherwise-unspecified &quot;restricted by URL and content safety policy,&quot; closing a real internal-network-reconnaissance vector this specific device&#39;s own port layout (Pi-hole, console-auth, the Conversation Service itself, llama-server, all on loopback) makes concretely dangerous, not abstractly.</li><li>Capability secrets: neither capability handles a credential (unlike Pi-hole&#39;s admin password) — SearXNG&#39;s local instance requires no authentication from Sovereign&#39;s side, so there is no credential-scoping requirement analogous to RFC-0006&#39;s.</li><li>Audit events for both capabilities follow RFC-0003 unchanged: the fact of invocation, classification, and outcome, never the query text or fetched content — household search/browsing intent is at least as sensitive as the DNS query behavior RFC-0006 already refused to log.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and Recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and Recovery&quot;">​</a></h2><ul><li>SearXNG unreachable: <code>web.search</code> fails through RFC-0003&#39;s normal bounded-execution failure path (a timeout or connection error), audited like any other capability failure, surfaced to the model as a failure it can narrate (&quot;I couldn&#39;t reach web search right now&quot;) — not a fabricated empty-results answer.</li><li>A <code>web.fetch</code> target that fails SSRF validation is rejected before any connection is attempted, with a specific error code (<code>FETCH_TARGET_REJECTED</code>) distinct from a genuine network failure, so the audit trail and any future debugging can tell &quot;we refused to try&quot; apart from &quot;we tried and failed.&quot;</li><li>A confirmation token that expires while genuinely pending (user hasn&#39;t answered) requires the proposal to be re-surfaced from scratch on the next message — per RFC-0004, this is not a system failure, only the token&#39;s deliberately short lifetime elapsing.</li><li>A <code>sovereign-conversation</code> process restart while a confirmation is pending invalidates that token (in-memory <code>ConfirmationStore</code>) — the client&#39;s next attempt to approve it hits <code>INVALID_CONFIRMATION</code> and must ask the model to propose again. Disclosed limitation, not silently swallowed.</li></ul><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and Migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and Migration&quot;">​</a></h2><p>No existing <code>web.search</code>/<code>web.fetch</code> capability to migrate from. The <code>pending_confirmation</code>/<code>confirmation</code> request-response fields are additive to <code>POST /api/v1/conversation/message</code>&#39;s existing shape — every turn that never hits a <code>required</code>-confirmation capability (every turn today, since <code>system.health</code>/Pi-hole are all <code>automatic</code>) is unaffected, verified by the existing <code>test_conversation_service.py</code> test suite continuing to pass unmodified. The confirmation wire format this RFC fixes is intentionally general (token/capability/version/arguments), not <code>web.search</code>/<code>web.fetch</code>-specific — confirmed in practice, not just in theory, when <a href="./0018-home-assistant-read-only-capability-mapping.html">RFC-0018</a> reused it unchanged for Home Assistant&#39;s own read-only capability pair (this RFC originally expected that reuse to come from Milestone 5&#39;s <em>mutating</em> slice specifically; it turned out to already be exercised by the read-only slice first, with no changes needed to the format itself).</p><h2 id="operations-and-observability" tabindex="-1">Operations and Observability <a class="header-anchor" href="#operations-and-observability" aria-label="Permalink to &quot;Operations and Observability&quot;">​</a></h2><ul><li>Policy state (<code>/data/sovereign/capabilities/policy.json</code>) should be inspectable the same way update/trust-rotation state already is (per RFC-0003&#39;s own Operations section for the general policy-state precedent) — a future Console settings panel reads and writes it, not a separate config path.</li><li>The capability audit log (RFC-0003, unchanged) is the operational record of how often <code>web.search</code>/<code>web.fetch</code> are proposed, approved, denied, or rejected by policy — useful for judging whether the confirmation flow is actually usable in practice (a denial/expiry rate that&#39;s too high might mean the UI is confusing, not that users don&#39;t want search) without needing a new monitoring surface.</li></ul><h2 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h2><ul><li>Contract-level tests mirroring RFC-0006&#39;s pattern: argument validation rejects anything outside <code>web.search</code>&#39;s schema (empty query, query over 500 chars, an invalid <code>time_range</code> value) and <code>web.fetch</code>&#39;s schema (non-http(s) scheme rejected before the SSRF check even runs).</li><li>SSRF policy tests, adversarial by design: a <code>web.fetch</code> proposal targeting <code>127.0.0.1</code> (any of this device&#39;s own real loopback ports), a private RFC1918 address, a link-local address, and a hostname that resolves to one of those (simulating rebinding) must all be rejected by <code>FETCH_TARGET_REJECTED</code> before any connection attempt — verified by mocking DNS resolution to return an internal address for an otherwise-innocuous-looking hostname, the direct test that the resolved- address check actually runs, not just a literal-string hostname denylist.</li><li>A redirect test: a mocked upstream response that redirects confirms <code>web.fetch</code> reports it (<code>redirected: true</code>, <code>final_url</code> set) rather than following it automatically.</li><li>Confirmation wire-format tests at the HTTP layer, extending <code>test_conversation_service.py</code>&#39;s existing pattern: a <code>required</code>- confirmation proposal produces a <code>pending_confirmation</code> object and no executed result; a correct <code>confirmation.token</code>/<code>approve: true</code> resubmission executes exactly once (token single-use, verified by a second resubmission with the same token failing); <code>approve: false</code> produces a denial appended to context; an unknown/expired/already-used token is rejected with <code>INVALID_CONFIRMATION</code>.</li><li>Policy-gate tests: <code>external_enabled: false</code> (the real default) rejects both capabilities at stage 3 before any confirmation is even generated; <code>external_enabled: true</code> allows the flow to proceed to the confirmation stage.</li><li>Fixture-backed tests for <code>web.search</code>/<code>web.fetch</code>&#39;s SearXNG-calling happy path, without requiring a live SearXNG instance for every test run — mirroring RFC-0006&#39;s own testing strategy for Pi-hole.</li><li>Once a real SearXNG instance is deployed (image-builder work, not this RFC), integration tests against it, followed by real-hardware qualification per this project&#39;s standing practice of a dated report under <code>docs/research/</code>.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li><strong>Restrict <code>web.fetch</code> to only URLs a prior <code>web.search</code> call in the same turn returned</strong>, rather than any model-proposed URL passing SSRF validation. Considered, but rejected: it would block a legitimate case (a user pastes a URL and asks about it) without closing a real gap the SSRF policy doesn&#39;t already close — the actual risk (reaching an internal service) is about destination, not provenance.</li><li><strong>Auto-approve <code>web.search</code> after the first explicit per-conversation opt-in</strong>, rather than per-invocation confirmation. Rejected: RFC-0003&#39;s confirmation model already fixed &quot;freshly-obtained... never a standing blanket approval&quot; as structural, not a per-capability choice, and loosening it would be a contract change to RFC-0003 itself, out of this RFC&#39;s scope (RFC-0003 §Drawbacks already names this exact tension as a possible future revisit, not decided here).</li><li><strong>Follow redirects up to a small bounded depth, re-validating each hop</strong>, instead of never following them. Considered as a real usability improvement (many URLs are one hop from <code>http</code> to <code>https</code>, or through a URL shortener), but rejected for this first pass: it&#39;s real additional implementation complexity (bounded-depth loop, re-validation per hop, distinguishing benign protocol-upgrade redirects from actual destination changes) for a capability that can already reach the intended content via an explicit second <code>web.fetch</code> proposal. Revisit if real usage shows single-hop redirects are common enough to be a genuine friction point.</li><li><strong>Cache SearXNG results or <code>web.fetch</code> content locally</strong> to reduce repeat external requests. Rejected: no retention policy exists for this data yet (RFC-0002 explicitly left conversation/capability data retention to a later data-inventory update), and caching household search/browsing content before that policy exists would be exactly the kind of privacy-relevant storage decision this project makes deliberately, not as a performance side-effect.</li></ul><h2 id="drawbacks-and-maintenance-cost" tabindex="-1">Drawbacks and Maintenance Cost <a class="header-anchor" href="#drawbacks-and-maintenance-cost" aria-label="Permalink to &quot;Drawbacks and Maintenance Cost&quot;">​</a></h2><ul><li>Every <code>web.search</code>/<code>web.fetch</code> call costs the user an extra round trip (propose → confirm → execute) compared to the milestone&#39;s other three capabilities, which all execute automatically. This is an accepted, structural consequence of RFC-0003&#39;s confirmation model, not a defect of this RFC&#39;s design — see Alternatives Considered on auto-approval.</li><li>The confirmation wire format adds real, permanent surface area to <code>POST /api/v1/conversation/message</code>&#39;s contract (two new optional fields, a new halting-round behavior) that every future client (Console today, anything else later) must handle correctly, not just the two capabilities that need it first.</li><li>SSRF validation adds an implementation and maintenance burden beyond what the pihole/system capabilities needed — a resolve-then-check step, a private/loopback/link-local address table to keep current, and redirect-handling logic — real, ongoing surface area, justified by this being the first capability where a model-influenced argument reaches the device&#39;s own network stack.</li></ul><h2 id="unresolved-questions" tabindex="-1">Unresolved Questions <a class="header-anchor" href="#unresolved-questions" aria-label="Permalink to &quot;Unresolved Questions&quot;">​</a></h2><p>None of the following block acceptance of the mapping and flows fixed above:</p><ul><li>The exact plain-text extraction method for <code>web.fetch</code> (which tags to strip, how to handle <code>&lt;script&gt;</code>/<code>&lt;style&gt;</code> content, whitespace normalization) is implementation detail, not architecture.</li><li>Whether <code>application/json</code> responses need any special handling beyond size/type checks (e.g., pretty-printing before truncation) — cosmetic, left to implementation.</li><li><s>The real JSON response schema from a live SearXNG instance</s> — resolved: a real live query against the exact pinned image (see <a href="./../research/searxng-deployment-assessment.html">searxng-deployment-assessment.md</a>&#39;s Addendum) confirmed <code>results[]</code> entries carry <code>title</code>/<code>url</code>/<code>content</code> among many other fields this RFC&#39;s schema deliberately doesn&#39;t surface — <code>content</code> maps to this RFC&#39;s <code>snippet</code>. The mapping itself is implementation detail; the fields exist as assumed.</li><li>Real upstream-engine blocking/CAPTCHA behavior from this device&#39;s residential IP, and what <code>web.search</code> should report to the model when an individual upstream engine fails but others in the same query succeed (partial results vs. treating any engine failure as a whole- capability failure) — needs real observation, not speculation.</li><li><s>Whether <code>/data/sovereign/capabilities/policy.json</code> should hold other future opt-in toggles (a general device-policy file) or stay <code>web.search</code>-specific until a second policy flag actually exists</s> — resolved by <a href="./0018-home-assistant-read-only-capability-mapping.html">RFC-0018</a> (Accepted): stays <code>web.search</code>-specific. Home Assistant&#39;s own enabled/base-URL/allowlist config lives in a separate <code>home-assistant.json</code> rather than growing <code>policy.json</code> into a general device-config blob, and its own executor-level toggle (<code>home_assistant_enabled</code>) is a distinct <code>policy_key</code> on the capability itself rather than a second field silently piggybacking on <code>external_enabled</code> — see <code>sovereign_capabilities.Capability</code>&#39;s <code>policy_key</code>/<code>policy_check</code> generalization, added specifically to keep these two independent (RFC-0018 found that without it, enabling web search would have silently enabled Home Assistant too).</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li><code>web.search</code> and <code>web.fetch</code> are registered against RFC-0003&#39;s contract with the schemas above, classified <code>read_only</code>/<code>external</code>/<code>required</code> (structural, unchanged from RFC-0003&#39;s own table).</li><li><code>bin/sovereign-conversation</code> reads <code>/data/sovereign/capabilities/policy.json</code> fresh per request and passes <code>external_enabled</code> into <code>process_turn()</code>, verified by a test that toggling the file&#39;s content between requests changes the outcome without a service restart.</li><li>A <code>required</code>-confirmation proposal halts its round and returns a <code>pending_confirmation</code> object containing the literal, undisclosed- free proposed arguments — verified by a test asserting the exact query/ URL text is present in the HTTP response, not merely a capability name.</li><li>Approving a pending confirmation executes the capability exactly once; a second approval attempt with the same token fails with <code>INVALID_CONFIRMATION</code> — verified directly (this is the single-use guarantee <code>ConfirmationStore</code> already provides at the executor layer; this criterion confirms the HTTP layer doesn&#39;t accidentally bypass it, e.g. by calling <code>invoke()</code> twice for one approval).</li><li>Denying a pending confirmation appends a denial (not a generic failure) to context and the turn continues without executing the capability.</li><li><code>web.fetch</code> rejects, before any network connection, a proposed URL whose resolved destination is loopback, RFC1918 private, or link-local — verified by the adversarial DNS-rebinding test in Testing Strategy, not just a literal-hostname denylist test.</li><li><code>web.fetch</code> does not automatically follow redirects — verified by a test asserting a redirect response is reported (<code>redirected: true</code>), not silently chased.</li><li><code>external_enabled: false</code> (the real default when <code>/data/sovereign/capabilities/policy.json</code> doesn&#39;t exist yet) rejects both capabilities at the policy stage, before any confirmation is generated — verified directly, confirming the milestone&#39;s &quot;disabled by default&quot; requirement is structurally true on a fresh device, not merely documented.</li><li>Existing tests (<code>test_conversation_service.py</code>, <code>test_capabilities.py</code>) continue to pass unmodified, confirming this RFC&#39;s additions are additive to the existing turn loop and executor, not a breaking change to <code>system.health</code>/Pi-hole&#39;s already-working paths.</li><li>The milestone&#39;s Exit Criteria bar for <code>web.search</code> specifically (&quot;Web search is disabled by default or explicitly enabled during onboarding, clearly signals external communication, and returns inspectable citations&quot;) is satisfied by the policy default, the confirmation disclosure, and <code>web.search</code>&#39;s structured <code>results</code> array respectively — each traceable to a specific Acceptance Criterion above, not asserted in the abstract.</li></ul><p>Explicitly <strong>not</strong> required for acceptance (named as necessary follow-up implementation, not blocking this RFC per this project&#39;s own precedent of separating proposal from build-out):</p><ul><li><s>The actual SearXNG image-builder embedding (<code>searxng-image.env</code>, a real pinned digest, the artifact/import/server systemd units).</s> Done, independent of this RFC&#39;s own review: <code>image-builder/sovereign/searxng-image.env</code> (real pinned digest) and <code>image-builder/sovereign/appliance/searxng/</code> (compose template, <code>settings.yml</code>, <code>start-searxng</code>/<code>stop-searxng</code>, three systemd units), unit-tested (<code>tests/test_searxng_deployment.py</code>).</li><li><s>The capability implementation itself.</s> Also done, independent of this RFC&#39;s own review, the same way the deployment above was: <code>sovereign_websearch.py</code> (both capabilities, the SSRF-safe fetch policy), the confirmation pause/resume wire format in <code>sovereign_conversation.py</code>/<code>bin/sovereign-conversation</code> (<code>PendingTurnStore</code>, <code>resume_turn()</code>, <code>pending_confirmation</code>/ <code>confirmation</code> request-response fields), and <code>/data/sovereign/capabilities/policy.json</code> policy-state reading, all unit-tested (<code>tests/test_websearch_capabilities.py</code>, extended <code>tests/test_conversation.py</code>/<code>test_conversation_service.py</code>). This project&#39;s implementation-before-formal-acceptance precedent (e.g. the Conversation Service itself shipped against RFC-0002/0003/0004 before those RFCs&#39; own Decision sections were filled in) applies here too — none of this is a substitute for project-owner review of the mapping and policy decisions this RFC actually proposes.</li><li><s>Console&#39;s approve/deny confirmation UI.</s> Also done, same precedent: a <code>.confirmation-card</code> in the Chat page (<code>console/index.html</code>, <code>console/assets/console.js</code>/<code>console.css</code>) discloses the literal capability name and arguments from <code>pending_confirmation</code>, with Deny/Approve controls that resume the turn via the <code>confirmation</code> request field, locking the composer while a decision is pending and clearing it on sign-out. Unit-tested (<code>tests/test_console.py</code>) and manually verified end-to-end (approve and deny) against a stub backend. A real, disclosed pre-existing UI bug was also found and fixed in the process: chat receipts previously always said &quot;stayed local&quot; regardless of classification — now accurate for <code>web.search</code>/<code>web.fetch</code>.</li><li><s>The settings toggle that writes <code>policy.json</code>.</s> Also done: <code>GET</code>/ <code>POST /api/v1/conversation/policy</code> (authenticated like <code>/message</code>, atomic write via a <code>.tmp</code> file + rename), and a labeled switch on Console&#39;s Chat page (<code>#chat-policy-row</code>) that loads the real state on sign-in and persists a change immediately, reverting the visible toggle if the write fails. Unit-tested (<code>tests/test_conversation.py</code>, <code>test_conversation_service.py</code>, <code>test_console.py</code>, <code>test_console_auth.py</code>) and manually verified end-to-end (toggle on, confirm a search is offered; toggle off, confirm it&#39;s rejected before any confirmation prompt) against a stub backend. <code>web_search_enabled</code> still defaults to <code>false</code> on any device that has never touched this toggle — the fail-safe default this RFC always required, now genuinely reachable and changeable from Console rather than only by an operator editing the file directly.</li><li><s>Real-hardware qualification of any of the above.</s> Done: see the <a href="./../research/web-search-and-confirmation-flow-hardware-qualification-report.html">web.search/confirmation flow hardware qualification report</a>. Real pinned digests pulled and run natively on the Raspberry Pi 5, real model + real inference, real SearXNG search, all five capabilities exercised through the real executor (including a real SSRF test against the device&#39;s own actual running services), a real confirmation round trip, and a real browser-authenticated pass driven by the project owner. Found and fixed one real bug in the process (the <code>web_search</code> policy toggle&#39;s <code>GET</code> request was missing its CSRF header, so it always failed against the real server — the <code>POST</code> path was unaffected). This was a manual smoke-test deployment on the project&#39;s standing qualification device (still <code>0.1.0-proof.3</code>, per the same precedent the llama-server deployment qualification already established), not a real signed release — the artifact/import systemd paths and the real <code>DynamicUser</code> sandbox for <code>sovereign-conversation.service</code> remain unexercised, named explicitly in that report&#39;s Limitations.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Accepted (2026-08-21, project creator, reviewed by Claude at the project creator&#39;s direction).</strong> The <code>web.search</code>/<code>web.fetch</code> mapping, the SSRF-safe fetch policy, the confirmation pause/resume wire format, and the <code>policy.json</code> design are accepted as this milestone&#39;s platform contract — all already implemented, hardware-smoke-tested (see the <a href="./../research/web-search-and-confirmation-flow-hardware-qualification-report.html">web.search/confirmation flow hardware qualification report</a>), and, as of RFC-0018, proven general enough for a second capability pair to reuse without modification.</p><p>This review re-checked the RFC against the current codebase rather than re-approving it as originally written. It held up well — the Acceptance Criteria section had already been kept current with strikethrough/resolution notes as implementation landed, a good practice this review continues rather than redoes. One real piece of drift was found and fixed: the Unresolved Questions entry about <code>policy.json</code>&#39;s scope was still marked open, even though RFC-0018 had already answered it (a separate <code>home-assistant.json</code>, not a shared file) three commits ago. The Compatibility section&#39;s prediction that <em>mutating</em> Home Assistant capabilities would be the first to reuse the confirmation wire format was also corrected — the read-only slice reused it first, unmodified, which is a stronger proof of the format&#39;s generality than what was originally predicted, not a discrepancy to paper over.</p><p>The Unresolved Questions above are accepted as non-blocking follow-ups, matching RFC-0003&#39;s own precedent for its own Unresolved Questions.</p>`,60)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
